import{_ as n,o as a,c as e,a6 as p}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"压缩与静态文件","description":"gzip 全部默认值的陷阱、gzip_vary 与代理缓存、sendfile/tcp_nopush 组合与 open_file_cache。","frontmatter":{"title":"压缩与静态文件","description":"gzip 全部默认值的陷阱、gzip_vary 与代理缓存、sendfile/tcp_nopush 组合与 open_file_cache。","source":"https://daiw.org/manual/nginx/static-perf"},"headers":[],"relativePath":"manual/tools/nginx/static-perf.md","filePath":"manual/tools/nginx/static-perf.md"}'),i={name:"manual/tools/nginx/static-perf.md"};function l(t,s,c,o,r,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="压缩与静态文件" tabindex="-1">压缩与静态文件 <a class="header-anchor" href="#压缩与静态文件" aria-label="Permalink to &quot;压缩与静态文件&quot;">​</a></h1><h2 id="gzip-的默认值几乎全都要改" tabindex="-1">gzip 的默认值几乎全都要改 <a class="header-anchor" href="#gzip-的默认值几乎全都要改" aria-label="Permalink to &quot;gzip 的默认值几乎全都要改&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip              on | off;         默认: off</span></span>
<span class="line"><span>gzip_types        mime-type ...;    默认: text/html</span></span>
<span class="line"><span>gzip_comp_level   1..9;             默认: 1</span></span>
<span class="line"><span>gzip_min_length   length;           默认: 20</span></span>
<span class="line"><span>gzip_proxied      ...;              默认: off</span></span>
<span class="line"><span>gzip_vary         on | off;         默认: off</span></span>
<span class="line"><span>gzip_http_version 1.0 | 1.1;        默认: 1.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>七个默认值里有五个在生产中都不合适</strong>，逐条看。</p><h3 id="gzip-types-默认只压-html" tabindex="-1">gzip_types：默认只压 HTML <a class="header-anchor" href="#gzip-types-默认只压-html" aria-label="Permalink to &quot;gzip\\_types：默认只压 HTML&quot;">​</a></h3><blockquote><p>Enables gzipping for specified MIME types <strong>in addition to</strong> &quot;text/html&quot;.</p></blockquote><p>关键是 <strong>in addition to</strong>——<code>text/html</code> 是<strong>无条件包含</strong>的，写不写都压。所以：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip_types text/css application/javascript application/json;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不需要（也不应该）再写 <code>text/html</code>。写了不报错，但冗余。</p><p>一份实用清单：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip_types</span></span>
<span class="line"><span>    text/plain</span></span>
<span class="line"><span>    text/css</span></span>
<span class="line"><span>    text/xml</span></span>
<span class="line"><span>    application/json</span></span>
<span class="line"><span>    application/javascript</span></span>
<span class="line"><span>    application/xml</span></span>
<span class="line"><span>    application/rss+xml</span></span>
<span class="line"><span>    image/svg+xml;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>不要压已压缩的格式</strong>：JPEG/PNG/WebP/MP4/ZIP/woff2。它们本身已压缩，再压 CPU 白烧、体积可能变大。</p><p>特别注意 <strong><code>woff2</code> 不要压</strong>（woff2 内建 Brotli），但 <strong><code>svg</code> 要压</strong>（SVG 是文本）。</p><p><code>gzip_types *;</code> 匹配所有类型——<strong>不要用</strong>，会连图片一起压。</p><h3 id="gzip-comp-level-默认-1" tabindex="-1">gzip_comp_level：默认 1 <a class="header-anchor" href="#gzip-comp-level-默认-1" aria-label="Permalink to &quot;gzip\\_comp\\_level：默认 1&quot;">​</a></h3><p>范围 1–9。<strong>默认 1</strong>（最快最弱）。</p><p>实践共识是 <strong>4–6</strong>：再往上压缩率提升极小而 CPU 消耗陡增。9 级相比 6 级通常只多省 1–2% 体积，却要多花一倍 CPU。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip_comp_level 5;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="gzip-min-length-默认-20-字节" tabindex="-1">gzip_min_length：默认 20 字节 <a class="header-anchor" href="#gzip-min-length-默认-20-字节" aria-label="Permalink to &quot;gzip\\_min\\_length：默认 20 字节&quot;">​</a></h3><p><strong>20 字节太小</strong>。小响应压缩后可能<strong>比原文更大</strong>（gzip 有固定头部开销），且每次压缩都有 CPU 成本。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip_min_length 1024;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>注意它<strong>依赖 <code>Content-Length</code></strong>——分块传输（无 <code>Content-Length</code>）时这个判断失效，会压缩所有响应。</p><h3 id="gzip-proxied-默认-off-←-反代场景的大坑" tabindex="-1">gzip_proxied：默认 off ← 反代场景的大坑 <a class="header-anchor" href="#gzip-proxied-默认-off-←-反代场景的大坑" aria-label="Permalink to &quot;gzip\\_proxied：默认 off ← 反代场景的大坑&quot;">​</a></h3><p><strong><code>gzip_proxied</code> 默认是 <code>off</code>，意味着「来自代理的请求一律不压缩」。</strong></p><p>判断依据是请求里<strong>有没有 <code>Via</code> 头</strong>——<a href="https://daiw.org/manual/http11/proxy-fields" target="_blank" rel="noreferrer"><code>Via</code> 是代理逐跳追加的</a>。所以：</p><ul><li>nginx 作为<strong>边缘</strong>直接面对用户 → 请求没有 <code>Via</code> → 正常压缩。</li><li>nginx 前面<strong>还有一层</strong> CDN/LB → 请求带 <code>Via</code> → <strong>默认完全不压缩</strong>。</li></ul><p>这是「本地测试有 gzip、上线后没有」的头号原因。</p><p>解法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip_proxied any;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其他取值用于按上游响应头细分（<code>expired</code>、<code>no-cache</code>、<code>no-store</code>、<code>private</code>、<code>auth</code>…），<code>any</code> 表示无条件压缩。</p><h3 id="gzip-vary-默认-off-←-缓存正确性问题" tabindex="-1">gzip_vary：默认 off ← 缓存正确性问题 <a class="header-anchor" href="#gzip-vary-默认-off-←-缓存正确性问题" aria-label="Permalink to &quot;gzip\\_vary：默认 off ← 缓存正确性问题&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip_vary on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>开启后响应会带 <code>Vary: Accept-Encoding</code>。</p><p><strong>这不是可选项，是缓存正确性的必需品。</strong> <a href="https://daiw.org/manual/http11/content-negotiation" target="_blank" rel="noreferrer">如 HTTP 协商章节所述</a>：漏发 <code>Vary</code> 会让 CDN/代理把 gzip 版本发给不支持 gzip 的客户端，得到一堆乱码。</p><p>只要开了 gzip 且前面有任何缓存层，<strong>必须</strong> <code>gzip_vary on;</code>。</p><h3 id="gzip-disable" tabindex="-1">gzip_disable <a class="header-anchor" href="#gzip-disable" aria-label="Permalink to &quot;gzip\\_disable&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip_disable &quot;msie6&quot;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>msie6</code> 是内置掩码，对应 <code>MSIE [4-6]\\.</code>。IE6 早已绝迹，这行现在<strong>可以删掉</strong>——它只是徒增一次正则匹配。</p><h2 id="预压缩-gzip-static" tabindex="-1">预压缩：gzip_static <a class="header-anchor" href="#预压缩-gzip-static" aria-label="Permalink to &quot;预压缩：gzip\\_static&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gzip_static on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>（需 <code>ngx_http_gzip_static_module</code>，编译时 <code>--with-http_gzip_static_module</code>）</p><p>直接返回<strong>预先压缩好的 <code>.gz</code> 文件</strong>：请求 <code>/app.js</code> 时，若存在 <code>/app.js.gz</code> 就直接发它。</p><p>优势明显：<strong>构建时压一次，运行时零 CPU</strong>，且可以用最高压缩级别（<code>gzip -9</code> 甚至 <code>zopfli</code>）。静态资源应优先用这个而不是实时压缩。</p><h2 id="sendfile-与-tcp-nopush" tabindex="-1">sendfile 与 tcp_nopush <a class="header-anchor" href="#sendfile-与-tcp-nopush" aria-label="Permalink to &quot;sendfile 与 tcp\\_nopush&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sendfile     on | off;    默认: off</span></span>
<span class="line"><span>tcp_nopush   on | off;    默认: off</span></span>
<span class="line"><span>tcp_nodelay  on | off;    默认: on</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sendfile    on;</span></span>
<span class="line"><span>tcp_nopush  on;</span></span>
<span class="line"><span>tcp_nodelay on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong><code>sendfile on</code></strong>——用 <code>sendfile()</code> 系统调用在内核态直接把文件送到 socket，<strong>零拷贝</strong>，不经过用户态缓冲。静态文件服务的关键优化。</p><p><strong><code>tcp_nopush on</code></strong>（Linux 的 <code>TCP_CORK</code>）——<strong>只在 <code>sendfile</code> 开启时生效</strong>。它让内核攒够一个完整数据包再发，避免响应头单独占一个小包。</p><p><strong><code>tcp_nodelay on</code></strong>（禁用 Nagle 算法）——默认已开。它与 <code>tcp_nopush</code> 看似矛盾，实际 nginx 处理得很好：传输大文件时用 nopush 攒包，最后一个包用 nodelay 立即发。<strong>三个一起开是标准配置</strong>。</p><p><code>sendfile</code> 与 <a href="/Front2Full/manual/tools/nginx/proxy"><code>proxy_buffering</code></a> 无关——前者针对<strong>本地文件</strong>，后者针对<strong>上游响应</strong>。</p><p>另外 <code>sendfile</code> 在某些虚拟化/网络文件系统上有已知问题，遇到静态文件传输异常可以试着关掉排查。</p><p>大文件场景可以配 <code>sendfile_max_chunk</code> 防止单个连接长时间独占 worker：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sendfile_max_chunk 2m;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="open-file-cache" tabindex="-1">open_file_cache <a class="header-anchor" href="#open-file-cache" aria-label="Permalink to &quot;open\\_file\\_cache&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open_file_cache          off | max=N [inactive=time];   默认: off</span></span>
<span class="line"><span>open_file_cache_valid    time;                          默认: 60s</span></span>
<span class="line"><span>open_file_cache_min_uses number;                        默认: 1</span></span>
<span class="line"><span>open_file_cache_errors   on | off;                      默认: off</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>缓存<strong>文件描述符、大小、修改时间</strong>与目录查找结果——避免每个请求都 <code>open()</code>/<code>stat()</code>。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open_file_cache          max=10000 inactive=60s;</span></span>
<span class="line"><span>open_file_cache_valid    60s;</span></span>
<span class="line"><span>open_file_cache_min_uses 2;</span></span>
<span class="line"><span>open_file_cache_errors   on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>它缓存的是元数据，不是文件内容。</strong> 但仍有一致性风险：文件在 <code>open_file_cache_valid</code> 期间被替换，nginx 可能仍返回旧的描述符。</p><p>静态资源用<strong>内容哈希文件名</strong>（<code>app.a1b2c3.js</code>）时完全无碍——文件名变了就是新文件。用固定文件名 + 原地覆盖部署时要注意这个窗口。</p><p><code>open_file_cache_errors on</code> 会连「文件不存在」也缓存——能挡住对不存在路径的反复探测，但部署新文件后需要等失效。</p><h2 id="expires" tabindex="-1">expires <a class="header-anchor" href="#expires" aria-label="Permalink to &quot;expires&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    expires [modified] time;</span></span>
<span class="line"><span>         expires epoch | max | off;</span></span>
<span class="line"><span>默认:    expires off;</span></span>
<span class="line"><span>上下文:  http, server, location, if in location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>设置 <a href="https://daiw.org/manual/http11/caching" target="_blank" rel="noreferrer"><code>Expires</code> 与 <code>Cache-Control</code></a> 响应头：</p><table tabindex="0"><thead><tr><th>值</th><th><code>Expires</code></th><th><code>Cache-Control</code></th></tr></thead><tbody><tr><td>正数时间</td><td>当前 + time</td><td><code>max-age=t</code></td></tr><tr><td><code>0</code></td><td>当前时间</td><td><code>max-age=0</code></td></tr><tr><td>负数</td><td>当前 −</td><td>time</td></tr><tr><td><code>epoch</code></td><td><code>Thu, 01 Jan 1970 00:00:01 GMT</code></td><td><code>no-cache</code></td></tr><tr><td><code>max</code></td><td><code>Thu, 31 Dec 2037 23:55:55 GMT</code></td><td>10 年</td></tr><tr><td><code>off</code></td><td>—</td><td>不修改</td></tr></tbody></table><p>只对这些状态码生效：<code>200 201 204 206 301 302 303 304 307 308</code>。</p><p>用变量做按类型区分（1.7.9+），官方示例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $sent_http_content_type $expires {</span></span>
<span class="line"><span>    default         off;</span></span>
<span class="line"><span>    application/pdf 42d;</span></span>
<span class="line"><span>    ~image/         max;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>expires $expires;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>带哈希的静态资源用 <code>max</code> + <code>immutable</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location ~* \\.[0-9a-f]{8}\\.(js|css)$ {</span></span>
<span class="line"><span>    expires    max;</span></span>
<span class="line"><span>    add_header Cache-Control &quot;public, immutable&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>immutable</code> 的语义见 <a href="https://daiw.org/manual/http11/caching" target="_blank" rel="noreferrer">HTTP 缓存扩展指令</a>——新鲜期内即使用户强刷也不发验证请求。</p><h2 id="一份静态站配置" tabindex="-1">一份静态站配置 <a class="header-anchor" href="#一份静态站配置" aria-label="Permalink to &quot;一份静态站配置&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http {</span></span>
<span class="line"><span>    sendfile    on;</span></span>
<span class="line"><span>    tcp_nopush  on;</span></span>
<span class="line"><span>    tcp_nodelay on;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    gzip              on;</span></span>
<span class="line"><span>    gzip_comp_level   5;</span></span>
<span class="line"><span>    gzip_min_length   1024;</span></span>
<span class="line"><span>    gzip_proxied      any;      # 反代后面必须</span></span>
<span class="line"><span>    gzip_vary         on;       # 缓存正确性必须</span></span>
<span class="line"><span>    gzip_types        text/plain text/css text/xml</span></span>
<span class="line"><span>                      application/json application/javascript</span></span>
<span class="line"><span>                      application/xml image/svg+xml;</span></span>
<span class="line"><span>    gzip_static       on;       # 优先用预压缩文件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    open_file_cache          max=10000 inactive=60s;</span></span>
<span class="line"><span>    open_file_cache_valid    60s;</span></span>
<span class="line"><span>    open_file_cache_min_uses 2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    server {</span></span>
<span class="line"><span>        root /var/www/site;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # 带哈希的资源：永久缓存</span></span>
<span class="line"><span>        location ~* \\.[0-9a-f]{8,}\\.(js|css|woff2)$ {</span></span>
<span class="line"><span>            expires    max;</span></span>
<span class="line"><span>            add_header Cache-Control &quot;public, immutable&quot;;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # HTML：不缓存，保证发版即生效</span></span>
<span class="line"><span>        location ~* \\.html$ {</span></span>
<span class="line"><span>            expires    -1;</span></span>
<span class="line"><span>            add_header Cache-Control &quot;no-cache&quot;;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        location / {</span></span>
<span class="line"><span>            try_files $uri $uri/ /index.html;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/access-limits">访问控制与限流</a>。</p>`,73)])])}const h=n(i,[["render",l]]);export{u as __pageData,h as default};
